'use strict';

// MODULES //

var isRowMajor = require( '@stdlib/ndarray-base-assert-is-row-major' );
var reinterpret = require( '@stdlib/strided-base-reinterpret-complex128' );


// MAIN //

/**
* Computes the Cartesian square for a double-precision complex floating-point strided array using alternative indexing semantics.
*
* ## Notes
*
* -   Pairs are stored as rows in the output matrix, where the first column contains the first element of each pair and the second column contains the second element.
*
* @param {NonNegativeInteger} N - number of indexed elements
* @param {Complex128Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Complex128Array} out - output array
* @param {integer} strideOut1 - stride length for the first dimension of `out`
* @param {integer} strideOut2 - stride length for the second dimension of `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {Complex128Array} output array
*
* @example
* var Complex128Array = require( '@stdlib/array-complex128' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var out = new Complex128Array( 8 );
*
* zcartesianSquare( x.length, x, 1, 0, out, 2, 1, 0 );
* // out => <Complex128Array>[ 1.0, 2.0, 1.0, 2.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0, 1.0, 2.0, 3.0, 4.0, 3.0, 4.0 ]
*/
function zcartesianSquare( N, x, strideX, offsetX, out, strideOut1, strideOut2, offsetOut ) { // eslint-disable-line max-len
	var viewX;
	var viewO;
	var so1;
	var so2;
	var re;
	var im;
	var sx;
	var ix;
	var jx;
	var io;
	var i;
	var j;

	if ( N <= 0 ) {
		return out;
	}
	// Reinterpret the complex arrays as real-valued arrays:
	viewX = reinterpret( x, 0 );
	viewO = reinterpret( out, 0 );

	// Adjust strides and offsets according to the real-valued arrays:
	sx = strideX * 2;
	so1 = strideOut1 * 2;
	so2 = strideOut2 * 2;
	ix = offsetX * 2;
	io = offsetOut * 2;
	if ( isRowMajor( [ strideOut1, strideOut2 ] ) ) {
		offsetX *= 2;
		for ( i = 0; i < N; i++ ) {
			re = viewX[ ix ];
			im = viewX[ ix+1 ];
			jx = offsetX;
			for ( j = 0; j < N; j++ ) {
				viewO[ io ] = re;
				viewO[ io+1 ] = im;
				viewO[ io+so2 ] = viewX[ jx ];
				viewO[ io+so2+1 ] = viewX[ jx+1 ];
				jx += sx;
				io += so1;
			}
			ix += sx;
		}
		return out;
	}
	// Column-major...

	// Fill the first column with each element repeated `N` times...
	for ( i = 0; i < N; i++ ) {
		re = viewX[ ix ];
		im = viewX[ ix+1 ];
		for ( j = 0; j < N; j++ ) {
			viewO[ io ] = re;
			viewO[ io+1 ] = im;
			io += so1;
		}
		ix += sx;
	}
	// Fill the second column by repeating the input array `N` times...
	io = ( offsetOut * 2 ) + so2;
	offsetX *= 2;
	for ( i = 0; i < N; i++ ) {
		jx = offsetX;
		for ( j = 0; j < N; j++ ) {
			viewO[ io ] = viewX[ jx ];
			viewO[ io+1 ] = viewX[ jx+1 ];
			jx += sx;
			io += so1;
		}
	}
	return out;
}


// EXPORTS //

module.exports = zcartesianSquare;
